import type { Handoff } from "@rhinohealth/ai-agents-shared";
import { jira } from "../jira.js";
import { ticketToPr } from "../workflows/ticket-to-pr.js";
import { QUERIES } from "./schedules.js";

// Runs as the Nova service account, so currentUser() is Nova.
const NOVA_JQL = "project = RH AND assignee = currentUser() AND statusCategory != Done ORDER BY updated ASC";

/** Who handed the ticket to Nova: the property /nova sets in Slack, else the latest assignee change to Nova. */
export async function requesterOf(key: string): Promise<string | undefined> {
  const fromSlack = await jira.issueProperty<string>(key, "nova.requester");
  if (fromSlack) return fromSlack;
  const history = await jira.changelog(key);  // oldest first
  const toNova = history.filter((h) => h.items.some((i) => i.field === "assignee" && i.to === jira.me));
  return toNova.at(-1)?.author.accountId;
}

// ensureSchedules (G3-28) makes this the poll-jira-nova schedule: every minute, overlap SKIP.
// startMatches hands each match to startRun (G3-25): queue ai-agents-nova, ID nova:<key>, USE_EXISTING.
QUERIES.set("nova", {
  name: "nova", agent: "nova", jql: NOVA_JQL, every: "1 minute",
  toStart: async (issue) => {  // async, and undefined skips a match: two small changes to G3-28's toStart
    const requester = await requesterOf(issue.key);
    if (!requester) return undefined;  // no assignment to Nova found: log it, don't start a run without an owner
    const handoff: Handoff = { key: issue.key, requester };
    return [ticketToPr, handoff];  // a second poll joins the open run
  },
});

// ai-agents/orchestrator/src/commands.ts: parse "@Nova <command> [text]" from a Jira comment (ADF body).
export const COMMANDS = ["start", "answer", "retry", "stop", "approve", "change"] as const;  // approve/change: G4-14
export type Command = (typeof COMMANDS)[number];
export interface NovaCommand {
  command: Command;
  text: string;  // the rest of the comment, e.g. an answer or a plan change
  author: string;  // Jira accountId of the person who wrote it
}
interface AdfNode { type: string; text?: string; attrs?: { id?: string }; content?: AdfNode[] }
interface JiraComment { author: { accountId: string }; body: AdfNode }
const flatten = (node: AdfNode): AdfNode[] => [node, ...(node.content ?? []).flatMap(flatten)];
const isCommand = (word: string): word is Command => (COMMANDS as readonly string[]).includes(word);
export function parseCommand(comment: JiraComment, novaAccountId: string): NovaCommand | undefined {
  const author = comment.author.accountId;
  if (author === novaAccountId) return undefined;  // never react to Nova's own comments
  const nodes = flatten(comment.body);
  const at = nodes.findIndex((n) => n.type === "mention" && n.attrs?.id === novaAccountId);
  if (at === -1) return undefined;
  const rest = nodes.slice(at + 1).filter((n) => n.type === "text").map((n) => n.text ?? "").join(" ").trim();
  const [word = "", ...words] = rest.split(" ");
  const command = word.toLowerCase();
  if (isCommand(command)) return { command, text: words.join(" ").trim(), author };
  return { command: "answer", text: rest, author };  // a plain reply to Nova counts as an answer
}

import { readFile } from "node:fs/promises";
import { query } from "@anthropic-ai/claude-agent-sdk";
import { JiraClient } from "@rhinohealth/ai-agents-shared";
import { z } from "zod";
export const PILOT_EXCLUDED = {  // a choice by people while we learn, not a wall: Nova stops and asks
  migration: ["cloud/rhinoCloud/rhinoCore/migrations/**", "client/rhinoOnPrem/*/migrations/**"],
  auth: ["cloud/rhinoCloud/rhinoDjango/login/**", "frontend/src/app/(auth)/**", "frontend/src/app/api/auth/**"],
  grpc_contract: ["common/fcp_common/rhinoAgentRpc/**"],
  infra: [".github/workflows/**", "**/docker-compose*.yml"],
};
export const Readiness = z.object({
  verdict: z.enum(["ready", "ask", "hand_back"]), reason: z.string(),
  kind: z.enum(["fe_bug", "be_bug", "add_tests", "small_feature", "dependency_bump", "docs", "other"]),
  size: z.enum(["small", "bigger", "fuzzy"]),  // bigger: grill; fuzzy: grill + 2-3 plans
  how_to_check: z.string(),  // empty = Nova sees no way to check it
  questions: z.array(z.string()).max(5),
  out_of_scope: z.array(z.enum(["migration", "auth", "grpc_contract", "infra"])),  // the keys of PILOT_EXCLUDED
});
export type Readiness = z.infer<typeof Readiness>;

export async function checkReadiness(key: string): Promise<Readiness> {
  const ticket = await JiraClient.fromEnv().ticketText(key);  // summary, description, comments, link titles; no attachments
  for await (const msg of query({ prompt: ticket, options: {
    model: "claude-sonnet-5-5", effort: "low", tools: [], settingSources: [],  // routing table; no repo, no VM
    systemPrompt: await readFile(new URL("../../prompts/readiness.md", import.meta.url), "utf8"),
    outputFormat: { type: "json_schema", schema: z.toJSONSchema(Readiness) },
    env: { ...process.env, ANTHROPIC_AUTH_TOKEN: mintRunToken({ agent: "nova", jira: key, run: `readiness:${key}` }),
      ANTHROPIC_CUSTOM_HEADERS: "x-ai-agents-step: ticket" },  // G0-13: the ticket rides in the run token
  } })) {
    if (msg.type === "result" && msg.subtype === "success") return Readiness.parse(msg.structured_output);
  }
  throw new Error(`readiness check for ${key} returned no result`);  // the activity fails and Temporal retries it
}

import { JiraClient } from "@rhinohealth/ai-agents-shared";
import { NOVA_STATE_FIELD } from "../jira-fields.js";  // "customfield_XXXXX": id from the Jira admin; not known yet
export type NovaState = "Checking" | "Planning" | "Awaiting approval" | "Working" | "PR open" | "Needs info" | "Stopped";
const NOTIFY = new Set<NovaState>(["Awaiting approval", "Needs info", "PR open"]);  // only the states that need a person
export interface Status {
  key: string;
  state: NovaState;
  doing: string;  // one plain line: "Writing the QA checks as tests"
  links: Record<string, string>;  // plan, slack thread, trace
  commentId?: string;  // kept in workflow state
}
function adf(s: Status) {
  const text = `Nova: ${s.state}. ${s.doing}  ` + Object.entries(s.links).map(([k, v]) => `${k}: ${v}`).join(" · ");
  return { type: "doc", version: 1, content: [{ type: "paragraph", content: [{ type: "text", text }] }] };
}
export async function setStatus(s: Status): Promise<string> {
  const jira = JiraClient.fromEnv();
  await jira.updateIssue(s.key, { [NOVA_STATE_FIELD]: { value: s.state } });
  if (s.commentId === undefined) return jira.addComment(s.key, adf(s));  // returns the new comment id
  await jira.editComment(s.key, s.commentId, adf(s), { notifyUsers: NOTIFY.has(s.state) });
  return s.commentId;
}

