import { test } from "node:test";
import assert from "node:assert/strict";
import { parseCommand } from "../src/commands.js";
const NOVA = "nova-account-id";
const mention = { type: "mention", attrs: { id: NOVA } };
const comment = (author: string, ...content: object[]) =>
  ({ author: { accountId: author }, body: { type: "doc", content: [{ type: "paragraph", content }] } });
test("@Nova stop is a stop command", () => {
  const c = comment("sean", mention, { type: "text", text: " stop" });
  assert.deepEqual(parseCommand(c, NOVA), { command: "stop", text: "", author: "sean" });
});
test("a plain reply to Nova is an answer", () => {
  const c = comment("sean", mention, { type: "text", text: " the empty state says No projects yet" });
  assert.equal(parseCommand(c, NOVA)?.command, "answer");
});
test("Nova's own comments are ignored", () => {
  assert.equal(parseCommand(comment(NOVA, mention, { type: "text", text: " stop" }), NOVA), undefined);
});
